public static void createConfigurationDirectory() {
    String userHome = System.getProperty("user.home");
    String configDirPath;

    if (System.getProperty("os.name").startsWith("Windows 2000")) {
        configDirPath = userHome + "\\Documents and Settings\\lf5";
    } else {
        configDirPath = userHome + "/.lf5";
    }

    File configDir = new File(configDirPath);
    if (!configDir.exists()) {
        if (configDir.mkdirs()) {
            System.out.println("Configuration directory created: " + configDirPath);
        } else {
            System.out.println("Failed to create configuration directory.");
        }
    } else {
        System.out.println("Configuration directory already exists: " + configDirPath);
    }
}

