    try {
        final byte[] bytes = str.toString().getBytes("UTF-8");
        final int length = bytes.length;
        if (lb.getWriteIndex() + length > lb.getCapacity()) {
            lb = session.grow(lb, length);
        }
        System.arraycopy(bytes, 0, lb.getBuffer(), lb.getWriteIndex(), length);
        lb.setWriteIndex(lb.getWriteIndex() + length);
        return lb;
    } catch (final UnsupportedEncodingException e) {
